	private final String displayName;
	private final SpriteEntry[] entries;

	GameSpriteCategory(String displayName, SpriteEntry[] entries)
	{
		this.displayName = displayName;
		this.entries = entries;
	}

	@Override
	public String toString()
	{
		return displayName;
	}

	public List<SpriteEntry> getEntryList()
	{
		return Arrays.asList(entries);
	}

	/**
	 * A single sprite entry with archive ID, frame index, and label.
	 */
	@Getter
	public static class SpriteEntry
	{
		private final int spriteId;
		private final int frame;
		private final String name;

		public SpriteEntry(int spriteId, int frame, String name)
		{
			this.spriteId = spriteId;
			this.frame = frame;
			this.name = name;
		}
	}

	private static SpriteEntry sprite(int id, int frame, String name)
	{
		return new SpriteEntry(id, frame, name);
	}
